import sys, random
sys.path.insert(0,'/workspace/submission'); sys.path.insert(0,'/workspace/tmp')
import t4
from planner import *
from fcflow import FlowGraph
seed=29
rnd=random.Random(seed)
n,links,caps,parts,rdem0=t4.gen(rnd)
period=rnd.choice([1,3,1000])
envelope={i:min(c,10**12) for i,c in enumerate(caps) if c>0}
cpl=[period*envelope.get(i,0) for i in range(len(links))]
cap={}
for lid,(u,v) in enumerate(links):
    if cpl[lid]>0:
        cap[(u,v)]=cap.get((u,v),0)+cpl[lid]; cap[(v,u)]=cap.get((v,u),0)+cpl[lid]
k=t4.max_multiplier(n,cap,parts,rdem0)
rdem={v:rdem0[v]*k for v in parts}
total=sum(rdem.values())
print('k',k,'rdem',rdem,'total',total)
# independent legacy-style test: SOURCE->b capacity r_b, check maxflow(SOURCE->v)>=D
def legacy_test(cap,parts,rdem,total,n):
    g=FlowGraph(n+1); SRC=n
    for (u,v),c in cap.items():
        if c>0: g.add_arc(u,v,c)
    for b in parts: g.add_arc(SRC,b,rdem[b])
    res={}
    for v in parts:
        res[v]=g.maxflow(SRC,v)
    return res
print('legacy test',legacy_test(cap,sorted(parts),rdem,total,n),'need >=',total)
print('k+1 test', legacy_test(cap,sorted(parts),{v:rdem0[v]*(k+1) for v in parts},sum(rdem0.values())*(k+1),n))
